// Google Places API (New) helper — NOT generated by Figma Make, safe from re-exports.
// Finds nearby cafes / libraries and maps them into the app's Spot shape.

export type LatLng = { lat: number; lng: number };

/** Structural copy of the `Spot` type in App.tsx (kept here so App.tsx stays Figma-owned). */
export type PlaceSpot = {
  id: number;
  name: string;
  area: string;
  walk: string;
  type: "coffee" | "library" | "outdoors";
  tags: string[];
  note: string;
  image: string;
  color: string;
  position: { left: string; top: string };
  rating: number;
  reviews: number;
  highlights: string[];
  openEarly: boolean;
  openLate: boolean;
  hours: string;
  address: string;
  /** Real coordinates (Places results). Sample spots without this get placed near the map center. */
  location?: LatLng;
  /** Google Place id (Places results, and Supabase spots that have one). */
  placeId?: string;
  /** Supabase spots.id uuid, when this spot exists in the community database. */
  dbId?: string;
};

/** University of Washington, Seattle. */
export const DEFAULT_CENTER_LATLNG: LatLng = { lat: 47.6553, lng: -122.3035 };

const FALLBACK_IMAGES = {
  coffee:
    "https://images.unsplash.com/photo-1758610605872-3195caed0bdd?crop=entropy&cs=tinysrgb&fit=crop&fm=jpg&q=85&w=900&h=700",
  library:
    "https://images.unsplash.com/photo-1694315643310-5a42072aa014?crop=entropy&cs=tinysrgb&fit=crop&fm=jpg&q=85&w=900&h=700",
  outdoors:
    "https://images.unsplash.com/photo-1669846125517-6ea5fd9dc9af?crop=entropy&cs=tinysrgb&fit=crop&fm=jpg&q=85&w=900&h=700",
} as const;

const COLORS = { coffee: "#e95743", library: "#475f9b", outdoors: "#597d47" } as const;

const PRICE: Record<string, string> = {
  FREE: "free",
  INEXPENSIVE: "$",
  MODERATE: "$$",
  EXPENSIVE: "$$$",
  VERY_EXPENSIVE: "$$$$",
};

/** Stable positive numeric id from a Place id string (App uses numeric ids). */
function numericId(placeId: string) {
  let hash = 0;
  for (let i = 0; i < placeId.length; i++) hash = (hash * 31 + placeId.charCodeAt(i)) | 0;
  return 1_000_000 + Math.abs(hash);
}

export function distanceMeters(a: LatLng, b: LatLng) {
  const rad = Math.PI / 180;
  const dLat = (b.lat - a.lat) * rad;
  const dLng = (b.lng - a.lng) * rad;
  const h =
    Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLng / 2) ** 2;
  return 2 * 6371000 * Math.asin(Math.sqrt(h));
}

function todaysHours(place: google.maps.places.Place) {
  const hours = place.regularOpeningHours;
  const today = new Date().getDay(); // 0 = Sunday (matches Places `day`)
  // weekdayDescriptions starts on Monday.
  const description = hours?.weekdayDescriptions?.[(today + 6) % 7];
  const label = description ? description.replace(/^[^:]+:\s*/, "") : "hours unknown";
  const periods = (hours?.periods ?? []).filter((period) => period.open.day === today);
  const always = hours?.periods?.length === 1 && !hours.periods[0].close; // open 24h
  const openEarly = always || periods.some((p) => p.open.hour < 8);
  const openLate =
    always ||
    periods.some((p) => !p.close || p.close.day !== today || p.close.hour >= 21);
  return { label, openEarly, openLate };
}

function toSpot(place: google.maps.places.Place, origin: LatLng): PlaceSpot | null {
  if (!place.location) return null;
  const location = { lat: place.location.lat(), lng: place.location.lng() };
  const types = [place.primaryType ?? "", ...(place.types ?? [])];
  const type: PlaceSpot["type"] = types.includes("library") ? "library" : "coffee";
  const [street = "", city = ""] = (place.formattedAddress ?? "").split(",").map((part) => part.trim());
  const meters = distanceMeters(origin, location);
  const { label, openEarly, openLate } = todaysHours(place);
  const price = place.priceLevel ? PRICE[String(place.priceLevel)] : undefined;
  let image: string = FALLBACK_IMAGES[type];
  try {
    image = place.photos?.[0]?.getURI({ maxWidth: 600 }) ?? image;
  } catch {
    // keep fallback image
  }
  return {
    id: numericId(place.id),
    placeId: place.id,
    name: place.displayName ?? "Study spot",
    area: city || "Nearby",
    walk: `${Math.max(1, Math.round(meters / 80))} min`,
    type,
    tags: [type === "library" ? "library" : "cafe", ...(price ? [price] : [])],
    note: place.formattedAddress ?? "Found nearby on Google Maps",
    image,
    color: COLORS[type],
    position: { left: "50%", top: "50%" }, // only used by the hand-drawn fallback map
    rating: place.rating ?? 0,
    reviews: place.userRatingCount ?? 0,
    highlights: [openLate ? "open late" : openEarly ? "open early" : "google pick", ...(price ? [price] : [])],
    openEarly,
    openLate,
    hours: label,
    address: street || place.formattedAddress || "",
    location,
  };
}

/**
 * Nearby cafes / coffee shops / libraries via Places API (New).
 * Requires the Maps JS API to be loaded already (APIProvider does that).
 */
export async function searchNearbySpots(center: LatLng, radius = 1500): Promise<PlaceSpot[]> {
  const { Place, SearchNearbyRankPreference } = (await google.maps.importLibrary(
    "places",
  )) as google.maps.PlacesLibrary;
  const { places } = await Place.searchNearby({
    fields: [
      "id",
      "displayName",
      "location",
      "formattedAddress",
      "rating",
      "userRatingCount",
      "priceLevel",
      "regularOpeningHours",
      "photos",
      "primaryType",
      "types",
    ],
    locationRestriction: { center, radius },
    includedTypes: ["cafe", "library", "coffee_shop"],
    maxResultCount: 20,
    rankPreference: SearchNearbyRankPreference.POPULARITY,
  });
  return places.map((place) => toSpot(place, center)).filter((spot): spot is PlaceSpot => spot !== null);
}

/**
 * Text search for the stamp and study-log typeaheads.
 * Biased toward the map center so nearby cafes, libraries, and stores come back first.
 */
export async function searchPlacesByText(text: string, center: LatLng = DEFAULT_CENTER_LATLNG): Promise<PlaceSpot[]> {
  const query = text.trim();
  if (!query || typeof google === "undefined" || !google.maps?.importLibrary) return [];
  const { Place } = (await google.maps.importLibrary("places")) as google.maps.PlacesLibrary & {
    Place: {
      searchByText: (request: {
        textQuery: string;
        fields: string[];
        locationBias: { center: LatLng; radius: number };
        maxResultCount: number;
      }) => Promise<{ places: google.maps.places.Place[] }>;
    };
  };
  const { places } = await Place.searchByText({
    textQuery: query,
    fields: [
      "id",
      "displayName",
      "location",
      "formattedAddress",
      "rating",
      "userRatingCount",
      "priceLevel",
      "regularOpeningHours",
      "photos",
      "primaryType",
      "types",
    ],
    locationBias: { center, radius: 20000 },
    maxResultCount: 15,
  });
  return places.map((place) => toSpot(place, center)).filter((spot): spot is PlaceSpot => spot !== null);
}
